import { describe, test, expect } from 'vitest';
import GBNF, { InputParseError, GrammarParseError, RuleType } from 'gbnf';

describe('smoke', () => {
  test('exercises the wider API surface', () => {
    const state = GBNF('root ::= [a-z] "=" [0-9]+ "\\n"', 'a=1');
    expect(state.size).toBe(2);
    expect(state.grammar).toBe('root ::= [a-z] "=" [0-9]+ "\\n"');
    expect(RuleType.CHAR).toBe('char');

    let err: unknown;
    try {
      state.add('x');
    } catch (e) {
      err = e;
    }
    expect(err).toBeInstanceOf(InputParseError);
    const inputError = err as InputParseError;
    expect(inputError.src).toBe('a=1x');
    expect(inputError.message).toBe(
      ['Failed to parse input string:', '', 'a=1x', '   ^'].join('\n')
    );
    expect(inputError.errorForMostRecentInput).toBe(
      ['Failed to parse input string:', '', 'x', '^'].join('\n')
    );

    let grammarErr: unknown;
    try {
      GBNF('root ::= foo');
    } catch (e) {
      grammarErr = e;
    }
    expect(grammarErr).toBeInstanceOf(GrammarParseError);
    expect((grammarErr as GrammarParseError).pos).toBe(9);
  });

  test('prints the graph', () => {
    const graph = GBNF('root ::= "ab" | [x-z]');
    // ParseState does not expose the graph; print via a fresh graph instead.
    expect(typeof graph.size).toBe('number');
  });
});

