import { readFileSync, writeFileSync } from 'node:fs';
import { test } from 'vitest';
import GBNF from 'gbnf';

test('dump differential results', () => {
  const cases: [string, string][] = JSON.parse(
    readFileSync('/tmp/cases.json', 'utf-8')
  );
  const results = cases.map(([grammar, initial]) => {
    try {
      const state = GBNF(grammar, initial);
      return {
        ok: true,
        rules: [...state].map((rule) =>
          'value' in rule
            ? { type: rule.type, value: rule.value }
            : { type: rule.type }
        ),
      };
    } catch (err) {
      return { ok: false, error: (err as Error).message };
    }
  });
  writeFileSync('/tmp/ts-results.json', JSON.stringify(results, null, 1));
});

